function piAirCreatedMs(t) {
  if (t == null || t === '') return 0;
  var n = Number(t);
  if (isFinite(n) && n > 0) return n < 1e12 ? n * 1000 : n;
  var d = Date.parse(String(t));
  return isFinite(d) ? d : 0;
}
function piClassifyAirbnbStay(b, month) {
  if (!b) return null;
  var channelYm = piYmFromTs(b.createdOnChannel);
  var hosthubYm = piYmFromTs(b.created);
  var createdYm = (channelYm === month || hosthubYm === month) ? month : (channelYm || hosthubYm);
  var cancelYm = piYmFromTs(b.cancelledAt);
  var inCreated = createdYm === month;
  var inCancel = !!(cancelYm === month && (b.cancelled || b.cancelledAt));
  if (!inCreated && !inCancel) return null;
  var stayKind = 'normal';
  if (inCancel) stayKind = 'cancel';
  else {
    var ch = piAirCreatedMs(b.createdOnChannel);
    var hh = piAirCreatedMs(b.created);
    if (ch && hh && hh - ch > 36 * 3600 * 1000) stayKind = 'extend';
  }
  var docs = stayKind === 'cancel' ? 2 : (stayKind === 'extend' ? 3 : 1);
  return {
    code: piAirCode(b),
    stayKind: stayKind,
    docs: docs,
    inCreated: inCreated,
    inCancel: inCancel,
    aptId: String(b.aptId || '').trim(),
    aptName: String(b.aptName || '').trim(),
    guestName: String(b.guestName || '').trim(),
    hosthubId: String(b.id || '').trim(),
    created: b.created != null ? b.created : null,
    createdOnChannel: b.createdOnChannel != null ? b.createdOnChannel : null
  };
}
function piEstimateAirbnbInvoices(month, bks) {
  var rank = { cancel: 3, extend: 2, normal: 1 };
