    if (piChan(b) !== 'airbnb') return;
    var rec = piClassifyAirbnbStay(b, month);
    if (!rec) return;
    if (!rec.code) {
      if (rec.inCreated) missing.push(Object.assign({}, rec, { kind: 'invoice' }));
      if (rec.inCancel) missing.push(Object.assign({}, rec, { kind: 'credit_note' }));
      return;
    }
    var prev = byCode[rec.code];
    if (!prev) { byCode[rec.code] = rec; return; }
    if ((rank[rec.stayKind] || 0) > (rank[prev.stayKind] || 0)) {
      byCode[rec.code] = Object.assign({}, prev, rec, { inCreated: prev.inCreated || rec.inCreated, inCancel: prev.inCancel || rec.inCancel });
    } else {
      prev.inCreated = prev.inCreated || rec.inCreated;
      prev.inCancel = prev.inCancel || rec.inCancel;
    }
  });
  var stays = Object.keys(byCode).sort().map(function (k) { return byCode[k]; });
  var estimate = { normal: 0, cancel: 0, extend: 0, docs: 0, stays: stays.length };
  stays.forEach(function (s) { estimate[s.stayKind] += 1; estimate.docs += s.docs; });
  return { stays: stays, missing: missing, estimate: estimate };
